sp_widget.client_script:
api.controller = function($scope, $window) {

    var c = this;


    /*
     * =====================================================
     * STATE
     * =====================================================
     */

    c.showForm = false;

    c.editMode = false;

    c.search = "";

    c.statusFilter = "";


    /*
     * =====================================================
     * EMPTY FORM
     * =====================================================
     */

    c.emptyJob = function() {

        return {

            sys_id: "",

            opportunity_id: "",

            opportunity_title: "",

            company: "",

            opportunity_type: "Job",

            opportunity_source: "TPO",

            job_description: "",

            location: "",

            required_skills: "",

            minimum_cgpa: "",

            eligible_branches: "",

            ctc_stipend: "",

            drive_date: "",

            application_deadline: "",

            status: "Open"

        };

    };


    c.job = c.emptyJob();


    /*
     * =====================================================
     * BACK TO DASHBOARD
     * =====================================================
     */

    c.backToDashboard = function() {

        $window.location.href =
            "?id=recruiter_dashboard";

    };


    /*
     * =====================================================
     * CREATE
     * =====================================================
     */

    c.openCreate = function() {

        c.job = c.emptyJob();

        c.editMode = false;

        c.showForm = true;

    };


    /*
     * =====================================================
     * EDIT
     * =====================================================
     */

    c.openEdit = function(job) {

        c.job = angular.copy(job);

        c.editMode = true;

        c.showForm = true;

        window.scrollTo(0, 0);

    };


    /*
     * =====================================================
     * CANCEL
     * =====================================================
     */

    c.cancelForm = function() {

        c.job = c.emptyJob();

        c.showForm = false;

        c.editMode = false;

    };


    /*
     * =====================================================
     * SAVE
     * =====================================================
     */

    c.saveJob = function() {

        if (!c.job.opportunity_id ||
            !c.job.opportunity_title ||
            !c.job.company) {

            alert(
                "Please enter Opportunity ID, Job Title and Company."
            );

            return;

        }


        var action =
            c.editMode ? "update" : "create";


        c.server.get({

            action: action,

            job: c.job

        }).then(function(response) {

            c.data = response.data;

            c.showForm = false;

            c.editMode = false;

            c.job = c.emptyJob();

        });

    };


    /*
     * =====================================================
     * CLOSE JOB
     * =====================================================
     */

    c.closeJob = function(job) {

        if (!job || !job.sys_id) {
            return;
        }


        var confirmClose =
            confirm(
                "Close this job opportunity?"
            );


        if (!confirmClose) {
            return;
        }


        c.server.get({

            action: "close",

            sys_id: job.sys_id

        }).then(function(response) {

            c.data = response.data;

        });

    };


    /*
     * =====================================================
     * SEARCH / FILTER
     * =====================================================
     */

    c.filterJob = function(job) {

        if (!job) {
            return false;
        }


        /*
         * SEARCH
         */

        if (c.search) {

            var text =
                c.search.toLowerCase().trim();


            var title =
                (job.opportunity_title || "")
                .toLowerCase();

            var company =
                (job.company_name || "")
                .toLowerCase();

            var location =
                (job.location || "")
                .toLowerCase();

            var skills =
                (job.required_skills || "")
                .toLowerCase();

            var opportunityId =
                (job.opportunity_id || "")
                .toLowerCase();


            var matches =
                title.indexOf(text) !== -1 ||
                company.indexOf(text) !== -1 ||
                location.indexOf(text) !== -1 ||
                skills.indexOf(text) !== -1 ||
                opportunityId.indexOf(text) !== -1;


            if (!matches) {
                return false;
            }

        }


        /*
         * STATUS
         */

        if (c.statusFilter) {

            if (job.status !== c.statusFilter) {
                return false;
            }

        }


        return true;

    };


    /*
     * =====================================================
     * CLEAR FILTER
     * =====================================================
     */

    c.clearFilters = function() {

        c.search = "";

        c.statusFilter = "";

    };


    /*
     * =====================================================
     * JOB COUNT
     * =====================================================
     */

    c.getJobCount = function() {

        if (!c.data || !c.data.jobs) {
            return 0;
        }


        var count = 0;


        c.data.jobs.forEach(function(job) {

            if (c.filterJob(job)) {
                count++;
            }

        });


        return count;

    };

};

sp_widget.css:
.jobs-page {
    min-height: 100vh;
    padding: 32px;
    background: #f4f6fb;
    font-family: Arial, sans-serif;
    color: #17213a;
}


/* HEADER */

.jobs-header {
    background: #ffffff;
    border: 1px solid #e4e8f1;
    border-radius: 16px;
    padding: 26px 30px;
    margin-bottom: 20px;

    display: flex;
    justify-content: space-between;
    align-items: center;

    box-shadow: 0 5px 18px rgba(31, 43, 75, 0.06);
}

.eyebrow {
    color: #5368d8;
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 1.4px;
    margin-bottom: 7px;
}

.jobs-header h1 {
    margin: 0;
    font-size: 27px;
    color: #14203b;
}

.jobs-header p {
    margin: 7px 0 0;
    color: #7d879c;
    font-size: 13px;
}

.header-actions {
    display: flex;
    gap: 10px;
}


/* BUTTONS */

.primary-btn {
    border: none;
    background: #5368d8;
    color: white;
    padding: 11px 18px;
    border-radius: 8px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 600;
}

.primary-btn:hover {
    background: #4357c7;
}

.secondary-btn {
    border: 1px solid #d9deea;
    background: white;
    color: #5368d8;
    padding: 10px 17px;
    border-radius: 8px;
    cursor: pointer;
    font-size: 12px;
    font-weight: 600;
}

.secondary-btn:hover {
    border-color: #5368d8;
}


/* FORM */

.job-form-card {
    background: white;
    border: 1px solid #e1e5ef;
    border-radius: 16px;
    padding: 25px;
    margin-bottom: 20px;

    box-shadow: 0 5px 18px rgba(31, 43, 75, 0.06);
}

.form-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;

    margin-bottom: 25px;
}

.form-header h2 {
    margin: 0;
    font-size: 20px;
}

.close-btn {
    border: none;
    background: #f1f3f8;
    color: #65708a;
    width: 32px;
    height: 32px;
    border-radius: 7px;
    cursor: pointer;
    font-size: 20px;
}

.form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 18px;
}

.form-group {
    display: flex;
    flex-direction: column;
}

.form-group.full {
    grid-column: 1 / -1;
}

.form-group label {
    font-size: 11px;
    color: #68738b;
    margin-bottom: 7px;
    font-weight: 600;
}

.form-group input,
.form-group select,
.form-group textarea {
    border: 1px solid #dce1eb;
    border-radius: 8px;
    padding: 11px 12px;
    outline: none;
    background: #fbfcfe;
    color: #26324d;
    font-size: 12px;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
    border-color: #5368d8;
    background: white;
}

.form-group textarea {
    resize: vertical;
}

.form-actions {
    margin-top: 24px;
    padding-top: 20px;
    border-top: 1px solid #edf0f5;

    display: flex;
    justify-content: flex-end;
    gap: 10px;
}


/* SEARCH */

.search-card {
    background: white;
    padding: 17px;
    border-radius: 14px;
    border: 1px solid #e3e7f0;

    display: flex;
    gap: 10px;

    margin-bottom: 16px;
}

.search-box {
    flex: 1;

    display: flex;
    align-items: center;

    border: 1px solid #dce1eb;
    border-radius: 8px;
    background: #fafbfe;

    padding: 0 12px;
}

.search-box span {
    font-size: 19px;
    color: #7d879c;
    margin-right: 9px;
}

.search-box input {
    width: 100%;
    border: none;
    outline: none;
    background: transparent;
    padding: 11px 0;
    font-size: 12px;
}

.search-card select {
    width: 150px;
    border: 1px solid #dce1eb;
    border-radius: 8px;
    padding: 10px;
    background: white;
    color: #29344e;
}


/* SUMMARY */

.summary-row {
    display: flex;
    justify-content: space-between;

    color: #7c879c;
    font-size: 12px;

    margin: 18px 3px;
}

.summary-row strong {
    color: #17213a;
    font-size: 15px;
}


/* GRID */

.job-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 18px;
}


/* JOB CARD */

.job-card {
    background: white;
    border: 1px solid #e1e5ee;
    border-radius: 15px;
    padding: 20px;

    box-shadow: 0 4px 14px rgba(31, 43, 75, 0.045);

    transition: 0.2s;
}

.job-card:hover {
    border-color: #bfc9f7;
    transform: translateY(-2px);
    box-shadow: 0 8px 22px rgba(31, 43, 75, 0.08);
}

.job-card-top {
    display: flex;
    gap: 12px;
    align-items: center;
}

.company-icon {
    width: 43px;
    height: 43px;
    border-radius: 10px;

    background: #eef1ff;
    color: #5368d8;

    display: flex;
    align-items: center;
    justify-content: center;

    font-weight: bold;
    font-size: 15px;
}

.job-card h3 {
    margin: 0;
    font-size: 15px;
    color: #17213a;
}

.job-card-top p {
    margin: 4px 0 0;
    color: #8992a5;
    font-size: 11px;
}


/* STATUS */

.job-status-row {
    display: flex;
    gap: 8px;
    margin: 17px 0;
}

.status-badge {
    background: #eaf8f1;
    color: #15965d;
    padding: 5px 9px;
    border-radius: 6px;
    font-size: 10px;
    font-weight: 600;
}

.job-type {
    background: #f0f2ff;
    color: #5368d8;
    padding: 5px 9px;
    border-radius: 6px;
    font-size: 10px;
}


/* DETAILS */

.job-details {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 15px;

    padding: 15px 0;

    border-top: 1px solid #edf0f5;
    border-bottom: 1px solid #edf0f5;
}

.job-details label {
    display: block;
    color: #929bad;
    font-size: 9px;
    margin-bottom: 5px;
}

.job-details span {
    color: #29344e;
    font-size: 11px;
    font-weight: 600;
}


/* SKILLS */

.job-skills {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;

    margin: 15px 0;
    min-height: 25px;
}

.skill-tag {
    background: #f0f2ff;
    color: #5368d8;
    padding: 5px 7px;
    border-radius: 5px;
    font-size: 9px;
}


/* FOOTER */

.job-footer {
    border-top: 1px solid #edf0f5;
    padding-top: 15px;

    display: flex;
    justify-content: space-between;
    align-items: center;
}

.job-footer small {
    display: block;
    color: #929bad;
    font-size: 9px;
    margin-bottom: 4px;
}

.job-footer strong {
    color: #29344e;
    font-size: 10px;
    font-weight: 500;
}

.job-actions {
    display: flex;
    gap: 6px;
}

.edit-btn,
.close-job-btn {
    border: none;
    border-radius: 6px;
    padding: 7px 10px;
    cursor: pointer;
    font-size: 10px;
}

.edit-btn {
    background: #f0f2ff;
    color: #5368d8;
}

.close-job-btn {
    background: #fff0f0;
    color: #d95353;
}


/* EMPTY */

.empty-state {
    grid-column: 1 / -1;

    background: white;
    border: 1px solid #e1e5ee;
    border-radius: 15px;

    padding: 60px 20px;

    text-align: center;
}

.empty-icon {
    width: 45px;
    height: 45px;
    margin: auto auto 15px;

    border-radius: 50%;
    background: #eef1ff;
    color: #5368d8;

    display: flex;
    align-items: center;
    justify-content: center;

    font-size: 22px;
}

.empty-state h3 {
    margin: 0 0 7px;
}

.empty-state p {
    color: #8992a5;
    font-size: 12px;
    margin-bottom: 18px;
}


/* RESPONSIVE */

@media (max-width: 1100px) {

    .job-grid {
        grid-template-columns: repeat(2, 1fr);
    }

}

@media (max-width: 750px) {

    .jobs-page {
        padding: 15px;
    }

    .jobs-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 18px;
    }

    .header-actions {
        width: 100%;
    }

    .header-actions button {
        flex: 1;
    }

    .search-card {
        flex-direction: column;
    }

    .search-card select {
        width: 100%;
    }

    .form-grid {
        grid-template-columns: 1fr;
    }

    .form-group.full {
        grid-column: auto;
    }

    .job-grid {
        grid-template-columns: 1fr;
    }

}

sp_widget.script:
(function() {

    data.jobs = [];
    data.companies = [];

    /*
     * =====================================================
     * LOAD COMPANIES
     * =====================================================
     */

    var companyGR = new GlideRecord('x_snc_campus360_company_master');
    companyGR.orderBy('name');
    companyGR.query();

    while (companyGR.next()) {

        data.companies.push({
            sys_id: companyGR.getUniqueValue(),
            name: companyGR.getDisplayValue()
        });

    }


    /*
     * =====================================================
     * CREATE JOB
     * =====================================================
     */

    if (input && input.action == 'create') {

        var newJob =
            new GlideRecord('x_snc_campus360_placement_opportunity');

        newJob.initialize();

        newJob.setValue(
            'opportunity_id',
            input.job.opportunity_id
        );

        newJob.setValue(
            'opportunity_title',
            input.job.opportunity_title
        );

        newJob.setValue(
            'company',
            input.job.company
        );

        newJob.setValue(
            'opportunity_type',
            input.job.opportunity_type
        );

        newJob.setValue(
            'opportunity_source',
            input.job.opportunity_source
        );

        newJob.setValue(
            'job_description',
            input.job.job_description
        );

        newJob.setValue(
            'location',
            input.job.location
        );

        newJob.setValue(
            'required_skills',
            input.job.required_skills
        );

        newJob.setValue(
            'minimum_cgpa',
            input.job.minimum_cgpa
        );

        newJob.setValue(
            'eligible_branches',
            input.job.eligible_branches
        );

        newJob.setValue(
            'ctc_stipend',
            input.job.ctc_stipend
        );

        newJob.setValue(
            'drive_date',
            input.job.drive_date
        );

        newJob.setValue(
            'application_deadline',
            input.job.application_deadline
        );

        newJob.setValue(
            'status',
            input.job.status || 'Open'
        );

        data.created_sys_id = newJob.insert();

    }


    /*
     * =====================================================
     * UPDATE JOB
     * =====================================================
     */

    if (input && input.action == 'update') {

        var updateJob =
            new GlideRecord('x_snc_campus360_placement_opportunity');

        if (updateJob.get(input.job.sys_id)) {

            updateJob.setValue(
                'opportunity_id',
                input.job.opportunity_id
            );

            updateJob.setValue(
                'opportunity_title',
                input.job.opportunity_title
            );

            updateJob.setValue(
                'company',
                input.job.company
            );

            updateJob.setValue(
                'opportunity_type',
                input.job.opportunity_type
            );

            updateJob.setValue(
                'opportunity_source',
                input.job.opportunity_source
            );

            updateJob.setValue(
                'job_description',
                input.job.job_description
            );

            updateJob.setValue(
                'location',
                input.job.location
            );

            updateJob.setValue(
                'required_skills',
                input.job.required_skills
            );

            updateJob.setValue(
                'minimum_cgpa',
                input.job.minimum_cgpa
            );

            updateJob.setValue(
                'eligible_branches',
                input.job.eligible_branches
            );

            updateJob.setValue(
                'ctc_stipend',
                input.job.ctc_stipend
            );

            updateJob.setValue(
                'drive_date',
                input.job.drive_date
            );

            updateJob.setValue(
                'application_deadline',
                input.job.application_deadline
            );

            updateJob.setValue(
                'status',
                input.job.status
            );

            updateJob.update();

        }

    }


    /*
     * =====================================================
     * CLOSE JOB
     * =====================================================
     */

    if (input && input.action == 'close') {

        var closeJob =
            new GlideRecord('x_snc_campus360_placement_opportunity');

        if (closeJob.get(input.sys_id)) {

            closeJob.setValue('status', 'Closed');

            closeJob.update();

        }

    }


    /*
     * =====================================================
     * LOAD JOBS
     * =====================================================
     */

    var jobsGR =
        new GlideRecord(
            'x_snc_campus360_placement_opportunity'
        );

    jobsGR.orderByDesc('sys_created_on');
    jobsGR.query();

    while (jobsGR.next()) {

        var job = {};

        job.sys_id =
            jobsGR.getUniqueValue();

        job.opportunity_id =
            jobsGR.getValue('opportunity_id') || '';

        job.opportunity_title =
            jobsGR.getValue('opportunity_title') || '';

        job.company =
            jobsGR.getValue('company') || '';

        job.company_name =
            jobsGR.getDisplayValue('company') || '';

        job.opportunity_type =
            jobsGR.getValue('opportunity_type') || '';

        job.opportunity_type_display =
            jobsGR.getDisplayValue('opportunity_type') || '';

        job.opportunity_source =
            jobsGR.getValue('opportunity_source') || '';

        job.job_description =
            jobsGR.getValue('job_description') || '';

        job.location =
            jobsGR.getValue('location') || '';

        job.required_skills =
            jobsGR.getValue('required_skills') || '';

        job.minimum_cgpa =
            jobsGR.getValue('minimum_cgpa') || '';

        job.eligible_branches =
            jobsGR.getValue('eligible_branches') || '';

        job.ctc_stipend =
            jobsGR.getValue('ctc_stipend') || '';

        job.drive_date =
            jobsGR.getValue('drive_date') || '';

        job.application_deadline =
            jobsGR.getValue('application_deadline') || '';

        job.status =
            jobsGR.getValue('status') || '';

        job.status_display =
            jobsGR.getDisplayValue('status') || '';

        data.jobs.push(job);

    }

})();
